// Retourne nullptr si l'equipe n'a pas (encore) de logo alternatif.
static const uint16_t* nhlAltLogoByAbbrev(const char* abbr){
  for(int i=0;i<NHL_ALT_LOGO_COUNT;i++) if(strcmp(NHL_ALT_LOGOS[i].abbr, abbr)==0) return NHL_ALT_LOGOS[i].data;
  return nullptr;
}
